// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // Fuzz the parameters to find cases where _baseToken == address(0) must be accepted by reference but rejected by mutant
    function testFuzz_property(address baseToken, address nft, uint128 virtualBaseTokenReserves, uint128 virtualNftReserves, uint56 changeFee, uint16 feeRate, bytes32 merkleRoot, bool useStolenNftOracle, bool payRoyalties) public {
        // Keep feeRate within admissible bound to avoid unrelated revert
        // but allow the fuzzer to choose wide values; constrain only to admissible range
        if (feeRate > 5000) feeRate = 5000;

        bool ok;
        // call initialize and capture whether it succeeded (reference should accept baseToken==address(0))
        try c.initialize(baseToken, nft, virtualBaseTokenReserves, virtualNftReserves, changeFee, feeRate, merkleRoot, useStolenNftOracle, payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: reference C accepts initialization even when baseToken == address(0).
        // Therefore, for all inputs, ok must be true. The mutant inserts `require(_baseToken != address(0))` and
        // will make ok == false for some inputs (those with baseToken == address(0)).
        assertTrue(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // fuzzed parameters include the deciding parameter: address _baseToken
    function testFuzz_property(address _baseToken, address _nft, uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves, uint56 _changeFee, uint16 _feeRate, bytes32 _merkleRoot, bool _useStolenNftOracle, bool _payRoyalties) public {
        // keep feeRate admissible per contract limits but wide otherwise
        _feeRate = uint16(bound(uint256(_feeRate), 0, 6000)); // allow up to 6000 to include invalid inputs too

        bool ok;
        // call initialize on the fresh instance and catch revert vs success
        try c.initialize(_baseToken, _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: Reference accepts initialization for all inputs (including _baseToken == address(0)).
        // We assert that when _baseToken != address(0) the call must succeed (both versions should),
        // and when _baseToken == address(0) the reference would succeed but mutant may revert.
        // To make a universal property that the reference satisfies for ALL inputs and the mutant breaks for SOME,
        // we assert that if _baseToken != address(0) then initialize MUST succeed on the reference instance.
        // (The mutant also accepts non-zero base tokens, so this assertion is true for the reference for all inputs
        // and the mutant cannot violate it.)

        if (_baseToken != address(0)) {
            assertTrue(ok);
        }
    }
}
